        id: directFooter
        Dialog {
            id: dlg
            objectName: "direct"
            width: 300
            height: 200
            standardButtons: Dialog.Save | Dialog.Cancel
            footer: DialogButtonBox {
                objectName: "directBox"
                standardButtons: dlg.standardButtons
                padding: 16
                spacing: 8
                alignment: Qt.AlignRight
                background: Item {}
                delegate: Button {}
            }
        }
