    function probe(comp, label) {
        const dlg = comp.createObject(tc)
        verify(dlg !== null, label + ": created")
        let accepted = 0, rejected = 0
        dlg.accepted.connect(function() { accepted++ })
        dlg.rejected.connect(function() { rejected++ })
        dlg.open()
        wait(50)
        verify(dlg.visible, label + ": opened visible")
        const box = dlg.contentItem.parent.findChild ? null : null
        let bx = null
        // find the DialogButtonBox
        bx = findBox(dlg)
        verify(bx !== null, label + ": box found")
        const save = bx.standardButton(Dialog.Save)
        verify(save !== null, label + ": save button exists")
        save.click()
        wait(50)
        console.log(label + " -> accepted=" + accepted + " rejected=" + rejected
                    + " visible=" + dlg.visible)
        dlg.destroy()
        return { accepted: accepted, rejected: rejected }
    }

    function findBox(item) {
        const kids = item.children
        for (let i = 0; i < kids.length; i++) {
            const c = kids[i]
            if (c && c.toString && c.toString().indexOf("DialogButtonBox") >= 0)
                return c
            const r = findBox(c)
            if (r) return r
